    }
    static int update(int value, int delta, int[] countDiv, int covered) {
        for (int d = 1; d * d <= value; d++) {
            if (value % d != 0) continue;
            int x = d;
            if (x < countDiv.length) {
                if (delta == 1 && countDiv[x] == 0) covered++;
                if (delta == -1 && countDiv[x] == 1) covered--;
                countDiv[x] += delta;
            }
            x = value / d;
            if (x != d && x < countDiv.length) {
                if (delta == 1 && countDiv[x] == 0) covered++;
                if (delta == -1 && countDiv[x] == 1) covered--;
                countDiv[x] += delta;
            }
        }
        return covered;
    }
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();
        int t = fs.nextInt();
        while (t-- > 0) {
