import sys

def update(value, delta, count_div, covered, m):
    d = 1
    while d * d <= value:
        if value % d == 0:
            x = d
            if x <= m:
                if delta == 1 and count_div[x] == 0:
                    covered += 1
                if delta == -1 and count_div[x] == 1:
                    covered -= 1
                count_div[x] += delta
            x = value // d
            if x != d and x <= m:
                if delta == 1 and count_div[x] == 0:
                    covered += 1
                if delta == -1 and count_div[x] == 1:
                    covered -= 1
                count_div[x] += delta
        d += 1
    return covered

def main():
